-- ═════════════════════════════════════════════════════════════════════════════
-- Oddsphere · Schema Migration V11 — source_type provenance tracking
-- ═════════════════════════════════════════════════════════════════════════════
--
-- WHY
--   V2.1's data-mode strategy (Part 2) supports three provenances for any
--   prediction:
--     mock     — generated by Phase 6's MockOddsProvider / MockSharpSignalProvider
--                / etc. The default during V1 launch.
--     manual   — pasted in by Daniel via the Phase 7.25 Admin Manual Upload
--                tool. Used to launch with real picks while paid APIs are off.
--     real_api — pulled from a live paid feed in Phase 8.
--
--   Capturing provenance on every row lets tracking and audit answer "which
--   of these picks came from a paid feed and which from mock data?" without
--   re-running provider state. It's also the column the V12 admin_audit_log
--   tags so admin actions are attributable to a data mode.
--
-- SHAPE
--   source_type TEXT, NOT NULL, DEFAULT 'mock'. CHECK constraint on the
--   3-value vocabulary: mock / manual / real_api.
--
-- COMPATIBILITY
--   ✓ Existing rows backfill to 'mock' via the column default — accurate,
--     because every row in V1 launch state IS from mock providers.
--   ✓ Existing INSERT paths keep working without code changes; new inserts
--     get 'mock' from the default. Phase 7.25 (manual) and Phase 8 (real_api)
--     code paths will explicitly set source_type when they ship.
--
-- ROLLBACK
--   ALTER TABLE game_predictions DROP COLUMN source_type;
--   ALTER TABLE prop_predictions DROP COLUMN source_type;
--   ALTER TABLE prediction_results DROP COLUMN source_type;
-- ═════════════════════════════════════════════════════════════════════════════

BEGIN;

-- ── game_predictions.source_type ──────────────────────────────────────────
ALTER TABLE game_predictions
  ADD COLUMN IF NOT EXISTS source_type TEXT NOT NULL DEFAULT 'mock';

ALTER TABLE game_predictions
  DROP CONSTRAINT IF EXISTS game_predictions_source_type_chk;
ALTER TABLE game_predictions
  ADD CONSTRAINT game_predictions_source_type_chk
  CHECK (source_type IN ('mock', 'manual', 'real_api'));

COMMENT ON COLUMN game_predictions.source_type IS
  'Data provenance for this prediction. mock = MockOddsProvider/etc (V1 default), manual = admin-pasted via Phase 7.25 tool, real_api = paid feed (Phase 8). Existing rows backfill to mock since that''s what generated them.';

-- ── prop_predictions.source_type ──────────────────────────────────────────
ALTER TABLE prop_predictions
  ADD COLUMN IF NOT EXISTS source_type TEXT NOT NULL DEFAULT 'mock';

ALTER TABLE prop_predictions
  DROP CONSTRAINT IF EXISTS prop_predictions_source_type_chk;
ALTER TABLE prop_predictions
  ADD CONSTRAINT prop_predictions_source_type_chk
  CHECK (source_type IN ('mock', 'manual', 'real_api'));

COMMENT ON COLUMN prop_predictions.source_type IS
  'Data provenance for this prop prediction. Same vocabulary as game_predictions.source_type.';

-- ── prediction_results.source_type ────────────────────────────────────────
ALTER TABLE prediction_results
  ADD COLUMN IF NOT EXISTS source_type TEXT NOT NULL DEFAULT 'mock';

ALTER TABLE prediction_results
  DROP CONSTRAINT IF EXISTS prediction_results_source_type_chk;
ALTER TABLE prediction_results
  ADD CONSTRAINT prediction_results_source_type_chk
  CHECK (source_type IN ('mock', 'manual', 'real_api'));

COMMENT ON COLUMN prediction_results.source_type IS
  'Data provenance carried forward from the prediction at resolve time, so tracking can segment ROI/hit-rate by source without rejoining predictions.';

COMMIT;

-- ═════════════════════════════════════════════════════════════════════════════
