--    FROM pg_constraint
--    WHERE conname IN (
--      'game_predictions_source_type_chk',
--      'prop_predictions_source_type_chk',
--      'prediction_results_source_type_chk'
--    );
--
-- 3. Backfill: every existing row reads 'mock':
--    SELECT 'game_predictions' AS tbl, source_type, COUNT(*) AS rows
--    FROM game_predictions GROUP BY source_type
--    UNION ALL SELECT 'prop_predictions', source_type, COUNT(*) FROM prop_predictions GROUP BY source_type
--    UNION ALL SELECT 'prediction_results', source_type, COUNT(*) FROM prediction_results GROUP BY source_type
--    ORDER BY tbl, source_type;
--
-- 4. Bad value rejected (this should ERROR):
--    UPDATE game_predictions SET source_type = 'spreadsheet' WHERE id = (SELECT id FROM game_predictions LIMIT 1);
